begin;
do $$
declare a uuid:=gen_random_uuid();t uuid:=gen_random_uuid();s uuid:=gen_random_uuid();s2 uuid:=gen_random_uuid();par uuid:=gen_random_uuid();ase uuid:=gen_random_uuid();tse uuid:=gen_random_uuid();sse uuid:=gen_random_uuid();s2se uuid:=gen_random_uuid();pse uuid:=gen_random_uuid();uid uuid;sid uuid;rol text;task text;yr uuid;c uuid;c2 uuid;family uuid;duty uuid;report uuid;pay uuid;account uuid;deposit uuid;r jsonb;v bigint;mo date:=date_trunc('month',public.app_ops_today());sy integer:=extract(year from public.app_ops_today())::integer-case when extract(month from public.app_ops_today())<7 then 1 else 0 end;checks integer:=0;
begin
 for uid,sid,rol in select * from(values(a,ase,'admin'),(t,tse,'teacher'),(s,sse,'student'),(s2,s2se,'student'),(par,pse,'parent'))x loop
 insert into auth.users(id,aud,role,email) values(uid,'authenticated','authenticated','stage20-'||uid||'@example.invalid');insert into auth.sessions(id,user_id) values(sid,uid);
 insert into public.profiles(id,username,full_name,contact_email) values(uid,'v'||replace(uid::text,'-',''),'Validation Stage 20','stage20-'||uid||'@example.invalid');
 insert into public.user_roles(user_id,role_code) values(uid,rol);insert into sim_murid_private.auth_accounts(user_id,must_change_password,profile_completed_at,verified_contact_email) values(uid,false,now(),'stage20-'||uid||'@example.invalid');insert into sim_murid_private.security_questions(user_id,question_code,answer_hash) values(uid,'q1',repeat('0',64));if rol='teacher' then insert into public.user_access_flags(user_id,teacher_email_verified_at) values(uid,now());end if;perform public.app_auth_claim(uid,sid,false);end loop;
 foreach task in array array['duty_teacher','student_mentor','committee_treasurer','savings_manager'] loop insert into public.user_assignments(user_id,assignment_code,valid_from,assigned_by) values(t,task,public.app_ops_today()-1,a);end loop;
 select id into yr from public.academic_years where start_year=sy;if yr is null then insert into public.academic_years(start_year) values(sy) returning id into yr;end if;
 insert into public.classes(academic_year_id,name,level,homeroom_teacher_id) values(yr,'VALID-20-7-'||left(a::text,8),7,t) returning id into c;insert into public.classes(academic_year_id,name,level) values(yr,'VALID-20-9-'||left(a::text,8),9) returning id into c2;
 insert into sim_murid_private.enrollments(student_id,class_id,academic_year_id,starts_on,created_by) values(s,c,yr,make_date(sy,7,1),a),(s2,c2,yr,make_date(sy,7,1),a);
 insert into sim_murid_private.student_guardians(student_id,parent_id,relationship,verified_by) values(s,par,'father',a);
 insert into sim_murid_private.family_groups(name,created_by) values('Validation siblings',a) returning id into family;insert into sim_murid_private.family_members(family_id,student_id,created_by) values(family,s,a),(family,s2,a);
 execute 'set local role service_role';
 select revision into v from sim_murid_private.operations_state;
 r=public.app_operations_write(a,ase,gen_random_uuid(),v,'duty',jsonb_build_object('type','roster','teacherId',t,'weekdays',jsonb_build_array(extract(isodow from public.app_ops_today())::integer)));if r->>'code'<>'saved' then raise exception 'Duty roster %',r;end if;checks=checks+1;
 if public.app_duty_confirmed(t,public.app_ops_today()) then raise exception 'Unconfirmed duty accepted';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(a,ase,gen_random_uuid(),v,'duty',jsonb_build_object('type','primary','teacherId',t));if r->>'code'<>'saved' then raise exception 'Duty confirm %',r;end if;duty=(r->>'id')::uuid;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'attendance',jsonb_build_object('type','batch','items',jsonb_build_array(jsonb_build_object('studentId',s,'classId',c,'date',public.app_ops_today(),'status','Hadir','notes','Validation'))));if r->>'code'<>'saved' then raise exception 'Attendance %',r;end if;checks=checks+1;
 if jsonb_array_length(public.app_operations_read(par,pse,'attendance',jsonb_build_object('start',public.app_ops_today(),'end',public.app_ops_today()))->'rows')<>1 then raise exception 'Parent attendance scope';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(a,ase,gen_random_uuid(),v,'mentoring',jsonb_build_object('type','assign','teacherId',t,'studentIds',jsonb_build_array(s)));if r->>'code'<>'saved' then raise exception 'Mentor assign %',r;end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'mentoring',jsonb_build_object('type','report','id',null,'studentId',s,'date',public.app_ops_today(),'kind','memorization','catalogId',null,'subject','Al-Ikhlas','predicate','Lancar','notes',''));if r->>'code'<>'saved' then raise exception 'Mentor report %',r;end if;report=(r->>'id')::uuid;checks=checks+1;
 if jsonb_array_length(public.app_operations_read(s2,s2se,'mentoring')->'rows')<>0 then raise exception 'Cross student report leak';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'fees',jsonb_build_object('type','payment','id',null,'studentId',s2,'date',public.app_ops_today(),'allocations',jsonb_build_array(jsonb_build_object('month',mo,'amount',50000)),'notes','Validation'));if r->>'code'<>'saved' then raise exception 'Fees %',r;end if;pay=(r->>'id')::uuid;checks=checks+1;
 if (select waived_student_id from sim_murid_private.payment_allocations where payment_id=pay and voided_at is null) is distinct from s then raise exception 'Wrong sibling waiver';end if;checks=checks+1;
 if (select sum(amount) from sim_murid_private.payment_allocations where payment_id=pay and voided_at is null)<>50000 then raise exception 'Waiver inflated cash';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','account','ownerId',s,'category','S'));if r->>'code'<>'saved' then raise exception 'Account %',r;end if;account=(r->>'id')::uuid;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','transaction','id',null,'accountId',account,'date',public.app_ops_today(),'kind','deposit','amount',200000,'reason','Initial balance'));if r->>'code'<>'saved' then raise exception 'Deposit %',r;end if;deposit=(r->>'id')::uuid;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','transaction','id',null,'accountId',account,'date',public.app_ops_today(),'kind','withdrawal','amount',123000,'reason','Validation withdrawal'));if r->>'code'<>'saved' then raise exception 'Withdraw %',r;end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','transaction','id',null,'accountId',account,'date',public.app_ops_today(),'kind','withdrawal','amount',100000,'reason','Overdraft attempt'));if r->>'code'<>'insufficient' then raise exception 'Overdraft accepted';end if;checks=checks+1;
 select revision into v from sim_murid_private.operations_state;r=public.app_operations_write(t,tse,gen_random_uuid(),v,'savings',jsonb_build_object('type','transaction','id',deposit,'accountId',account,'date',public.app_ops_today(),'kind','deposit','amount',150000,'reason','Correct deposit'));if r->>'code'<>'saved' then raise exception 'Correction %',r;end if;checks=checks+1;
 if (select sum(delta) from sim_murid_private.savings_transactions where account_id=account)<>27000 then raise exception 'Ledger mismatch';end if;checks=checks+1;
 if (public.app_operations_read(par,pse,'savings')#>>'{summary,balance}')::bigint<>27000 then raise exception 'Parent balance mismatch';end if;checks=checks+1;
 if has_function_privilege('authenticated','public.app_operations_write(uuid,uuid,uuid,bigint,text,jsonb)','execute') then raise exception 'Direct write exposed';end if;checks=checks+1;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','sim_murid_private') and c.relkind='r' and not c.relrowsecurity) then raise exception 'RLS missing';end if;checks=checks+1;
 raise notice '% operations assertions passed',checks;
end$$;
rollback;
